"import { NextResponse } from 'next/server';
import { encodeAgentState, Persona } from '@/lib/simulator';

export async function POST(request: Request) {
  try {
    const body = await request.json();

    if (!body || !body.persona || !body.persona.name || !body.persona.domain) {
      return NextResponse.json(
        { error: 'Invalid request payload. Expected { persona: { name, domain } }' },
        { status: 400 }
      );
    }

    const persona: Persona = body.persona;

    // The "agentId" completely encapsulates the state (who they are + when they started).
    // This makes the entire application stateless and serverless-friendly!
    const initAt = Date.now();
    const agentId = encodeAgentState(persona, initAt);

    return NextResponse.json({ agentId });
  } catch (error) {
    return NextResponse.json(
      { error: 'Failed to parse JSON body' },
      { status: 400 }
    );
  }
}"

"import { NextResponse } from 'next/server';
import { generateFeed } from '@/lib/simulator';

export async function GET(request: Request) {
  const { searchParams } = new URL(request.url);
  const agentId = searchParams.get('agentId');

  if (!agentId) {
    return NextResponse.json(
      { error: 'Missing agentId parameter' },
      { status: 400 }
    );
  }

  const posts = generateFeed(agentId);

  // If the agentId is invalid, generateFeed returns an empty array.
  // The API requirements state: "If no posts exist, return: { posts: [] }"
  return NextResponse.json({ posts });
}"

