"import fs from 'fs';
import path from 'path';

// Using a local JSON file to simulate persistent storage on a stateful deployment (like Render).
const DATA_FILE = path.join(process.cwd(), 'data.json');

export interface Persona {
  name: string;
  domain: string;
}

export interface Post {
  id: string;
  createdAt: string;
  text: string;
  rationale: string;
  sources: string[];
}

export interface RejectedTopic {
  title: string;
  reason: string;
  rejectedAt: string;
}

export interface AgentData {
  agentId: string;
  persona: Persona | null;
  posts: Post[];
  rejected: RejectedTopic[];
}

function readData(): AgentData {
  if (!fs.existsSync(DATA_FILE)) {
    return { agentId: '', persona: null, posts: [], rejected: [] };
  }
  try {
    const raw = fs.readFileSync(DATA_FILE, 'utf-8');
    return JSON.parse(raw);
  } catch (e) {
    return { agentId: '', persona: null, posts: [], rejected: [] };
  }
}

function writeData(data: AgentData) {
  fs.writeFileSync(DATA_FILE, JSON.stringify(data, null, 2), 'utf-8');
}

export function initAgent(persona: Persona): string {
  const agentId = `agent_${Date.now()}`;
  writeData({
    agentId,
    persona,
    posts: [],
    rejected: []
  });
  return agentId;
}

export function getAgentData(): AgentData {
  return readData();
}

export function savePost(post: Post) {
  const data = readData();
  data.posts.unshift(post); // newest first
  writeData(data);
}

export function saveRejections(rejections: RejectedTopic[]) {
  const data = readData();
  data.rejected = [...rejections, ...data.rejected];
  writeData(data);
}
"

